    64	        hostname,
    65	        method: request.method,
    66	        path: requestPath,
    67	        headers: {
    68	            ...request.headers,
    69	            host: hostname,
    70	            // eslint-disable-next-line @typescript-eslint/naming-convention
    71	            'user-agent': request.headers['user-agent']?.concat(' Development-NewDot/1.0'),
